 d=dict(zip(keys,vals)); c=C[pid]; d.update({"paper_id":pid,"title":P[pid]["title"],"subtheme":c["subtheme"]}); notes.append(d); md += [f"## {i}. {d['subtheme']}","",f"**Paper:** [{d['title']}]({P[pid]['paper_url']})",f"**Evidence:** D3; PDF SHA-256 `{c['pdf_sha256']}`; full text captured.",""]
